import { useState } from "react";
import axios from "axios";
import LocationForm from "../components/LocationForm";
import MapComponent from "../components/MapComponent";

const FeedPage = () => {
    const [locations, setLocations] = useState([{ lat: "", lng: "" }]);
    const [centralPoint, setCentralPoint] = useState(null);
    const [places, setPlaces] = useState([]);

    const findMeetingSpot = async () => {
        const { data: central } = await axios.post("http://localhost:5000/api/locations/central-point", { locations });
        setCentralPoint(central);

        const { data: placesData } = await axios.post("http://localhost:5000/api/places/nearby-places", {
            lat: central.lat,
            lng: central.lng,
            type: "cafe"
        });

        setPlaces(placesData);
    };

    return (
        <div>
            <h1>Find Optimal Meeting Spot</h1>
            <LocationForm locations={locations} setLocations={setLocations} findMeetingSpot={findMeetingSpot} />
            {centralPoint && <MapComponent centralPoint={centralPoint} places={places} />}
        </div>
    );
};

export default FeedPage;
